mapper.insert:
insert into registration (
  empnum, memnum, shnum, regcreated, regupdatedat, regnote
)
select
  #{empNum}, #{memNum}, #{shNum}, current_timestamp, current_timestamp, #{regNote}
where
  /* 유효 회원권 존재 */
  exists (
    select 1 from voucher_log
    where memnum = #{memNum}
      and enddate >= now()
  )
  /* 잔여 PT > 0 */
  and (
    select ifnull(sum(countchange), 0)
    from pt_log
    where memnum = #{memNum}
  ) > 0
  /* shNum 중복 없음 */
  and not exists (
    select 1 from registration
    where shnum = #{shNum}
  )

mapper.update:
